import numpy as np

def independent_risks(S):
    # S: one row per risk factor, one column per instrument
    S = np.array(S, dtype=float)
    return int(np.linalg.matrix_rank(S))

def can_hedge(S, e):
    # e: the book's exposure to each risk factor
    S = np.array(S, dtype=float)
    both = np.column_stack([S, e])
    r = np.linalg.matrix_rank
    return bool(r(both) == r(S))
